import{_ as a,o as s,c as t,a3 as i}from"./chunks/framework.I6s8z2kk.js";const m=JSON.parse('{"title":"Packages and memberships","description":"","frontmatter":{},"headers":[],"relativePath":"user/client/packages-memberships.md","filePath":"user/client/packages-memberships.md"}'),r={name:"user/client/packages-memberships.md"};function n(o,e,c,l,h,p){return s(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="packages-and-memberships" tabindex="-1">Packages and memberships <a class="header-anchor" href="#packages-and-memberships" aria-label="Permalink to &quot;Packages and memberships&quot;">​</a></h1><h2 id="packages" tabindex="-1">Packages <a class="header-anchor" href="#packages" aria-label="Permalink to &quot;Packages&quot;">​</a></h2><p>A <strong>package</strong> is a bundle of sessions for one service, bought once at a lower price per session.</p><ul><li>Buy it from the service. It is <strong>pending</strong> until payment succeeds, then <strong>active</strong>.</li><li>Packages are always paid online, never on arrival.</li><li>A center can pause a package. A paused package is not shown and cannot be bought, but packages you already own keep working.</li><li>Book a session from your package. It is <strong>confirmed immediately</strong> and costs nothing more. Each booking uses one session.</li><li>When the sessions run out the package is <strong>exhausted</strong>. It also <strong>expires</strong> after its validity period, counted from when it became active.</li><li>A package linked to a trainer can only be used with that trainer.</li><li>You can give a package a <strong>knight name</strong> of your own and change it any time. The center can mark a package as <strong>controlled</strong>; you cannot change that.</li><li>Cancelling a session booked with a package gives the session back.</li></ul><h2 id="memberships" tabindex="-1">Memberships <a class="header-anchor" href="#memberships" aria-label="Permalink to &quot;Memberships&quot;">​</a></h2><p>A <strong>membership</strong> gives you free visits to a center for a period.</p><ul><li>Buy it online. It becomes <strong>active</strong> after payment and lasts for its duration, counted from activation.</li><li>Check in for a <strong>visit</strong> while it is active. Visits are free and confirmed immediately.</li><li>Each membership has a <strong>limit of visits per day</strong>.</li><li>You are reminded before a package or membership expires.</li></ul><h2 id="where-to-see-them" tabindex="-1">Where to see them <a class="header-anchor" href="#where-to-see-them" aria-label="Permalink to &quot;Where to see them&quot;">​</a></h2><p><strong>My packages</strong> and <strong>My memberships</strong> list yours with their status (pending, active, exhausted, expired, cancelled).</p>',9)])])}const d=a(r,[["render",n]]);export{m as __pageData,d as default};
